import {useEffect,useMemo,useRef,useState,type FormEvent,type ReactNode} from 'react';
import {Activity,Apple,BarChart3,BookOpen,BriefcaseBusiness,CalendarDays,Check,ChevronLeft,ChevronRight,Cloud,CloudOff,Download,Dumbbell,Flame,FolderKanban,GraduationCap,LayoutDashboard,LogIn,LogOut,Medal,Menu,Minus,MonitorUp,Moon,Pause,Play,Plus,RefreshCw,Search,Settings,Target,Timer,Trash2,Trophy,Upload,WalletCards,X} from 'lucide-react';
import type {AppBackup,AppState,ApplicationStatus,Book,CalendarEvent,EventCategory,FinanceType,MealType,ProjectStatus,SportType,UemTopicStatus,View} from './types';
import {DAY,addDays,isoDate,isoToday,localDate,seedState,uid} from './data';
import {downloadTextFile,useAppState} from './storage';
import {searchBooks,searchExercises} from './services/catalog';
import {cloudEnabled,getSession,pullCloud,pushCloud,signIn,signOut,signUp,supabase} from './services/supabase';

const today=()=>isoToday();
const labels:Record<EventCategory,string>={study:'Estudo',workout:'Treino',reading:'Leitura',meal:'Refeição',work:'Trabalho',personal:'Pessoal',sleep:'Sono',sport:'Esporte'};
const nav:Array<[View,string,ReactNode]>=[
 ['today','Hoje',<LayoutDashboard/>],['calendar','Calendário',<CalendarDays/>],['focus','Foco',<Timer/>],['study','Estudos',<GraduationCap/>],['uem','UEM',<Medal/>],['library','Biblioteca',<BookOpen/>],['workouts','Academia',<Dumbbell/>],['sports','Esportes',<Activity/>],['nutrition','Nutrição',<Apple/>],['sleep','Sono',<Moon/>],['projects','Projetos',<FolderKanban/>],['career','Carreira',<BriefcaseBusiness/>],['finance','Finanças',<WalletCards/>],['goals','Metas',<Target/>],['yearly','Ano',<BarChart3/>],['review','Revisão',<RefreshCw/>],['settings','Configurações',<Settings/>]
];
const key=(id:string,date:string)=>`${id}@${date}`;
const occurs=(e:CalendarEvent,date:string)=>date>=e.date&&(e.repeat==='daily'||(e.repeat==='weekdays'&&localDate(date).getDay()>0&&localDate(date).getDay()<6)||(e.repeat==='weekly'&&localDate(date).getDay()===localDate(e.date).getDay())||e.date===date);
const eventsFor=(state:AppState,date:string)=>state.events.filter(e=>occurs(e,date)).sort((a,b)=>a.start.localeCompare(b.start));
const weekStart=(d:string)=>{const x=localDate(d);return addDays(d,1-(x.getDay()||7))};
const longDate=(d:string)=>new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(localDate(d));
const shortDate=(d:string)=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(localDate(d));
const money=(v:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
const n=(v:FormDataEntryValue|null,fallback=0)=>Number(v)||fallback;
const s=(v:FormDataEntryValue|null)=>String(v||'').trim();
const clamp=(v:number,a=0,b=100)=>Math.min(b,Math.max(a,v));
const pct=(a:number,b:number)=>b?Math.round(a/b*100):0;

function Card({children,className=''}:{children:ReactNode;className?:string;key?:string}){return <section className={`panel ${className}`}>{children}</section>}
function Head({kicker,title,sub,actions}:{kicker:string;title:string;sub:string;actions?:ReactNode}){return <div className="page-head"><div><small>{kicker}</small><h1>{title}</h1><p>{sub}</p></div>{actions&&<div className="actions">{actions}</div>}</div>}
function PanelHead({kicker,title,action}:{kicker?:string;title:string;action?:ReactNode}){return <div className="panel-head"><div>{kicker&&<small>{kicker}</small>}<h2>{title}</h2></div>{action}</div>}
function Progress({value}:{value:number}){return <div className="progress"><i style={{width:`${clamp(value)}%`}}/></div>}
function Empty({icon,title,text}:{icon:ReactNode;title:string;text:string}){return <div className="empty"><span>{icon}</span><b>{title}</b><p>{text}</p></div>}
function Metric({label,value,sub,tone='blue'}:{label:string;value:string;sub:string;tone?:string}){return <Card className={`metric ${tone}`}><small>{label}</small><strong>{value}</strong><p>{sub}</p></Card>}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function FormActions(){return <div className="form-actions"><button className="btn primary" type="submit"><Plus/>Salvar</button></div>}

export default function App(){
 const[state,setState]=useAppState();
 const[view,setView]=useState<View>('today');const[selectedDate,setSelectedDate]=useState(today());const[calendarCursor,setCalendarCursor]=useState(localDate(today()));const[sidebar,setSidebar]=useState(false);
 const[bookQuery,setBookQuery]=useState('');const[bookResults,setBookResults]=useState<Awaited<ReturnType<typeof searchBooks>>>([]);const[bookBusy,setBookBusy]=useState(false);
 const[exerciseQuery,setExerciseQuery]=useState('');const[exerciseResults,setExerciseResults]=useState<Awaited<ReturnType<typeof searchExercises>>>([]);const[exerciseBusy,setExerciseBusy]=useState(false);const[selectedPlan,setSelectedPlan]=useState(state.workoutPlans[0]?.id||'');
 const[focusSeconds,setFocusSeconds]=useState(50*60);const[focusRunning,setFocusRunning]=useState(false);const[focusLabel,setFocusLabel]=useState('Estudo profundo');
 const[session,setSession]=useState<Awaited<ReturnType<typeof getSession>>>(null);const[cloudStatus,setCloudStatus]=useState('Local');const[authEmail,setAuthEmail]=useState('');const[authPassword,setAuthPassword]=useState('');
 const focusStarted=useRef<number|null>(null);
 const t=today();const ws=weekStart(t);

 useEffect(()=>{getSession().then(setSession).catch(()=>{});if(!supabase)return;const {data}=supabase.auth.onAuthStateChange((_e,x)=>setSession(x));return()=>data.subscription.unsubscribe()},[]);
 useEffect(()=>{if(!focusRunning)return;const id=window.setInterval(()=>setFocusSeconds(v=>{if(v<=1){window.clearInterval(id);setFocusRunning(false);const minutes=Math.max(1,Math.round(((focusStarted.current?Date.now()-focusStarted.current:50*60000))/60000));setState(x=>({...x,focusLogs:[{id:uid('focus'),date:t,minutes,label:focusLabel},...x.focusLogs]}));focusStarted.current=null;return 50*60}return v-1}),1000);return()=>window.clearInterval(id)},[focusRunning,focusLabel,setState,t]);

 const stats=useMemo(()=>{
  const studyMinutes=state.studyLogs.filter(x=>x.date>=ws&&x.date<=addDays(ws,6)).reduce((a,x)=>a+x.minutes,0)+state.focusLogs.filter(x=>x.date>=ws&&x.date<=addDays(ws,6)).reduce((a,x)=>a+x.minutes,0);
  const pages=state.readingLogs.filter(x=>x.date>=ws&&x.date<=addDays(ws,6)).reduce((a,x)=>a+x.pages,0);
  const workouts=state.workoutLogs.filter(x=>x.date>=ws&&x.date<=addDays(ws,6)).length;
  const sport=state.sports.filter(x=>x.date>=ws&&x.date<=addDays(ws,6)).reduce((a,x)=>a+x.duration,0);
  const completedHabits=Object.entries(state.habitCompletions).filter(([k,v])=>v&&k.endsWith(`@${t}`)).length;
  const ev=eventsFor(state,t);const completedEvents=ev.filter(e=>state.eventCompletions[key(e.id,t)]).length;
  const dailyTotal=ev.length+state.habits.length;const dailyDone=completedEvents+completedHabits;
  const xp=Object.entries(state.habitCompletions).reduce((sum,[k,v])=>{if(!v)return sum;const id=k.split('@')[0];return sum+(state.habits.find(h=>h.id===id)?.xp||10)},0)+state.studyLogs.reduce((a,x)=>a+Math.round(x.minutes/5),0)+state.focusLogs.reduce((a,x)=>a+Math.round(x.minutes/5),0)+state.workoutLogs.length*50+state.readingLogs.reduce((a,x)=>a+Math.min(50,x.pages),0)+state.sports.length*30+state.projects.filter(x=>x.status==='concluido').length*200;
  const level=Math.floor(xp/500)+1;
  let streak=0;for(let i=0;i<365;i++){const d=addDays(t,-i);const done=state.habits.some(h=>state.habitCompletions[key(h.id,d)])||state.studyLogs.some(x=>x.date===d)||state.focusLogs.some(x=>x.date===d);if(done)streak++;else if(i>0)break;}
  return{studyMinutes,pages,workouts,sport,dailyDone,dailyTotal,dailyPct:pct(dailyDone,dailyTotal),xp,level,streak};
 },[state,t,ws]);

 const patch=<K extends keyof AppState>(field:K,value:AppState[K]|((v:AppState[K])=>AppState[K]))=>setState(prev=>({...prev,[field]:typeof value==='function'?(value as (v:AppState[K])=>AppState[K])(prev[field]):value}));
 const remove=<K extends keyof AppState>(field:K,id:string)=>patch(field,((arr:any)=>Array.isArray(arr)?arr.filter((x:any)=>x.id!==id):arr) as any);

 const backup=()=>downloadTextFile(`meu-dia-v3-${t}.json`,JSON.stringify({version:3,exportedAt:new Date().toISOString(),data:state} satisfies AppBackup,null,2));
 const restore=async(file:File)=>{try{const x=JSON.parse(await file.text()) as AppBackup;if(x.version!==3||!x.data)throw new Error();setState({...seedState,...x.data,version:3});alert('Backup restaurado.')}catch{alert('Backup inválido.')}};
 const reset=()=>{if(confirm('Restaurar os dados iniciais? Isto apaga os dados locais atuais.'))setState(seedState)};
 const exportIcs=()=>{const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const esc=(x='')=>x.replace(/[;,]/g,' ');const out=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Meu Dia//PT-BR'];state.events.forEach(e=>{out.push('BEGIN:VEVENT',`UID:${e.id}@meudia`,`DTSTAMP:${stamp}`,`DTSTART:${e.date.replace(/-/g,'')}T${e.start.replace(':','')}00`,`DTEND:${e.date.replace(/-/g,'')}T${e.end.replace(':','')}00`,`SUMMARY:${esc(e.title)}`,`DESCRIPTION:${esc(e.notes)}`);if(e.repeat==='daily')out.push('RRULE:FREQ=DAILY');if(e.repeat==='weekdays')out.push('RRULE:FREQ=WEEKLY;BYDAY=MO,TU,WE,TH,FR');if(e.repeat==='weekly')out.push('RRULE:FREQ=WEEKLY');out.push('END:VEVENT')});out.push('END:VCALENDAR');downloadTextFile(`meu-dia-${t}.ics`,out.join('\r\n'),'text/calendar')};

 const Layout=({children}:{children:ReactNode})=><div className="app"><button className="mobile-menu" onClick={()=>setSidebar(true)}><Menu/></button><aside className={sidebar?'open':''}><div className="brand"><div><CalendarDays/></div><span><b>Meu Dia</b><small>Personal OS</small></span><button className="close-side" onClick={()=>setSidebar(false)}><X/></button></div><div className="level-card"><div><Trophy/></div><span><small>NÍVEL {stats.level}</small><b>{stats.xp} XP</b><Progress value={(stats.xp%500)/5}/></span></div><nav>{nav.map(([id,label,ico])=><button key={id} className={view===id?'active':''} onClick={()=>{setView(id);setSidebar(false)}}>{ico}<span>{label}</span></button>)}</nav><div className="side-foot"><Flame/><span><b>{stats.streak} dias</b><small>sequência ativa</small></span></div></aside><main>{children}</main></div>;

 function Today(){const ev=eventsFor(state,t);return <><Head kicker="PAINEL PESSOAL" title="Bom dia, Zé." sub={`${longDate(t)} · faça o essencial muito bem.`}/><div className="metrics"><Metric label="PROGRESSO" value={`${stats.dailyPct}%`} sub={`${stats.dailyDone}/${stats.dailyTotal} itens`} tone="blue"/><Metric label="ESTUDO" value={`${(stats.studyMinutes/60).toFixed(1)}h`} sub="esta semana" tone="purple"/><Metric label="TREINOS" value={`${stats.workouts}`} sub="academia na semana" tone="green"/><Metric label="STREAK" value={`${stats.streak}d`} sub={`nível ${stats.level} · ${stats.xp} XP`} tone="amber"/></div><div className="dashboard"><Card><PanelHead kicker="AGENDA" title="Seu dia" action={<button className="btn ghost" onClick={()=>setView('calendar')}>Abrir calendário</button>}/><div className="agenda">{ev.map(e=>{const k=key(e.id,t);const done=!!state.eventCompletions[k];return <button key={e.id} className={`event ${e.category} ${done?'done':''}`} onClick={()=>patch('eventCompletions',v=>({...v,[k]:!v[k]}))}><time>{e.start}<small>{e.end}</small></time><span className="dot"/><span><b>{e.title}</b><small>{labels[e.category]}{e.notes?` · ${e.notes}`:''}</small></span><i>{done&&<Check/>}</i></button>})}</div></Card><div className="right-stack"><Card><PanelHead kicker="HÁBITOS" title="Hoje"/><div className="habit-list">{state.habits.map(h=>{const k=key(h.id,t);const done=!!state.habitCompletions[k];return <button key={h.id} className={done?'done':''} onClick={()=>patch('habitCompletions',v=>({...v,[k]:!v[k]}))}><span className="habit-check">{done&&<Check/>}</span><div><b>{h.name}</b><small>{h.targetPerWeek}x/semana · +{h.xp} XP</small></div></button>})}</div></Card><Card><PanelHead kicker="CAPTURA" title="Notas do dia"/><textarea className="notes" value={state.dailyNotes[t]||''} onChange={e=>patch('dailyNotes',v=>({...v,[t]:e.target.value}))} placeholder="Aprendizados, ideias e ajustes para amanhã..."/></Card></div></div></>}

 function Calendar(){const cursor=calendarCursor,setCursor=setCalendarCursor;const y=cursor.getFullYear(),m=cursor.getMonth();const first=new Date(y,m,1,12);const start=new Date(first.getTime()-first.getDay()*DAY);const days=Array.from({length:42},(_,i)=>new Date(start.getTime()+i*DAY));const chosen=eventsFor(state,selectedDate);const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('events',v=>[...v,{id:uid('event'),title:s(f.get('title')),date:s(f.get('date')),start:s(f.get('start')),end:s(f.get('end')),category:s(f.get('category')) as EventCategory,repeat:s(f.get('repeat')) as any,notes:s(f.get('notes'))}]);e.currentTarget.reset()};return <><Head kicker="PLANEJAMENTO" title="Calendário" sub="Organize cada bloco do dia e mantenha rotinas recorrentes." actions={<button className="btn ghost" onClick={exportIcs}><Download/>Exportar .ics</button>}/><div className="calendar-layout"><Card className="calendar"><div className="calendar-top"><button className="icon" onClick={()=>setCursor(new Date(y,m-1,1,12))}><ChevronLeft/></button><h2>{new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(first)}</h2><button className="icon" onClick={()=>setCursor(new Date(y,m+1,1,12))}><ChevronRight/></button></div><div className="weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=><span key={x}>{x}</span>)}</div><div className="month-grid">{days.map(d=>{const ds=isoDate(d);const items=eventsFor(state,ds);return <button key={ds} className={`${d.getMonth()!==m?'muted':''} ${ds===t?'today':''} ${ds===selectedDate?'selected':''}`} onClick={()=>setSelectedDate(ds)}><b>{d.getDate()}</b>{items.slice(0,3).map(x=><span key={x.id} className={x.category}>{x.start} {x.title}</span>)}</button>})}</div></Card><div className="right-stack"><Card><PanelHead kicker="DIA" title={longDate(selectedDate)}/>{chosen.length?<div className="chosen-list">{chosen.map(x=><div className={`chosen ${x.category}`} key={x.id}><span className="dot"/><div><b>{x.title}</b><small>{x.start}–{x.end} · {labels[x.category]}</small></div>{x.repeat==='none'&&<button className="icon danger" onClick={()=>remove('events',x.id)}><Trash2/></button>}</div>)}</div>:<Empty icon={<CalendarDays/>} title="Dia livre" text="Nenhum compromisso cadastrado."/>}</Card><Card><PanelHead kicker="NOVO" title="Adicionar atividade"/><form className="form" onSubmit={submit}><Field label="Título"><input name="title" required/></Field><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={selectedDate} required/></Field><Field label="Categoria"><select name="category" defaultValue="personal">{Object.entries(labels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field></div><div className="cols"><Field label="Início"><input name="start" type="time" defaultValue="09:00" required/></Field><Field label="Fim"><input name="end" type="time" defaultValue="10:00" required/></Field></div><Field label="Repetição"><select name="repeat"><option value="none">Não repetir</option><option value="daily">Todos os dias</option><option value="weekdays">Segunda a sexta</option><option value="weekly">Semanal</option></select></Field><Field label="Observações"><textarea name="notes"/></Field><FormActions/></form></Card></div></div></>}

 function Focus(){const mins=String(Math.floor(focusSeconds/60)).padStart(2,'0'),secs=String(focusSeconds%60).padStart(2,'0');const todayFocus=state.focusLogs.filter(x=>x.date===t).reduce((a,x)=>a+x.minutes,0);return <><Head kicker="FOCO PROFUNDO" title="Pomodoro" sub="Cronometre o trabalho real e transforme foco em histórico."/><div className="focus-layout"><Card className="timer-card"><span className="timer-kicker">SESSÃO ATUAL</span><div className="timer-display">{mins}:{secs}</div><input className="focus-label" value={focusLabel} onChange={e=>setFocusLabel(e.target.value)}/><div className="timer-buttons"><button className="btn primary big" onClick={()=>{if(!focusRunning){focusStarted.current=Date.now();setFocusRunning(true)}else setFocusRunning(false)}}>{focusRunning?<><Pause/>Pausar</>:<><Play/>Iniciar</>}</button><button className="btn ghost" onClick={()=>{setFocusRunning(false);setFocusSeconds(50*60);focusStarted.current=null}}>50 min</button><button className="btn ghost" onClick={()=>{setFocusRunning(false);setFocusSeconds(25*60);focusStarted.current=null}}>25 min</button></div></Card><Card><PanelHead kicker="HOJE" title={`${todayFocus} minutos focados`}/><div className="history">{state.focusLogs.filter(x=>x.date===t).map(x=><div key={x.id}><Timer/><span><b>{x.label}</b><small>{x.minutes} min</small></span></div>)}</div></Card></div></>}

 function Study(){const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('studyLogs',v=>[{id:uid('study'),subjectId:s(f.get('subject')),date:s(f.get('date')),minutes:n(f.get('minutes')),topic:s(f.get('topic')),notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};return <><Head kicker="APRENDIZADO" title="Estudos" sub="Controle tempo, matéria e conteúdo — não apenas horas vagas."/><div className="split"><Card><PanelHead kicker="REGISTRAR" title="Sessão de estudo"/><form className="form" onSubmit={submit}><Field label="Matéria"><select name="subject">{state.subjects.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Minutos"><input name="minutes" type="number" defaultValue="60" min="1"/></Field></div><Field label="Conteúdo"><input name="topic" placeholder="Ex.: Função quadrática" required/></Field><Field label="Observações"><textarea name="notes" placeholder="Erros, dúvidas e revisão..."/></Field><FormActions/></form></Card><Card><PanelHead kicker="SEMANA" title="Distribuição por matéria"/><div className="subject-bars">{state.subjects.map(sub=>{const m=state.studyLogs.filter(x=>x.subjectId===sub.id&&x.date>=ws&&x.date<=addDays(ws,6)).reduce((a,x)=>a+x.minutes,0)+state.focusLogs.filter(x=>x.subjectId===sub.id&&x.date>=ws&&x.date<=addDays(ws,6)).reduce((a,x)=>a+x.minutes,0);return <div key={sub.id}><span><b>{sub.name}</b><small>{(m/60).toFixed(1)}h / {(sub.weeklyGoalMinutes/60).toFixed(0)}h</small></span><Progress value={pct(m,sub.weeklyGoalMinutes)}/></div>})}</div></Card></div><Card><PanelHead kicker="HISTÓRICO" title="Sessões recentes"/><div className="table">{state.studyLogs.slice(0,20).map(x=><div className="tr" key={x.id}><span>{shortDate(x.date)}</span><b>{state.subjects.find(su=>su.id===x.subjectId)?.name||'Matéria'}</b><span>{x.topic}</span><strong>{x.minutes} min</strong><button className="icon danger" onClick={()=>remove('studyLogs',x.id)}><Trash2/></button></div>)}</div></Card></>}

 function Uem(){const updateTopic=(id:string,changes:Partial<AppState['uemTopics'][number]>)=>patch('uemTopics',v=>v.map(x=>x.id===id?{...x,...changes}:x));const accuracy=state.uemTopics.reduce((a,x)=>a+x.correct,0),questions=state.uemTopics.reduce((a,x)=>a+x.questions,0);const prep=Math.round(state.uemTopics.reduce((a,x)=>a+({'nao-iniciado':0,'estudando':35,'revisao':70,'dominado':100}[x.status]),0)/Math.max(1,state.uemTopics.length));const addEssay=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('essays',v=>[{id:uid('essay'),date:s(f.get('date')),theme:s(f.get('theme')),score:n(f.get('score')),notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};const addMock=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('mocks',v=>[{id:uid('mock'),date:s(f.get('date')),score:n(f.get('score')),maxScore:n(f.get('maxScore'),100),correct:n(f.get('correct')),total:n(f.get('total')),notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};return <><Head kicker="VESTIBULAR" title="UEM" sub="Edital vivo: conteúdo, questões, redações e simulados no mesmo lugar."/><div className="metrics"><Metric label="PREPARAÇÃO" value={`${prep}%`} sub="conteúdo dominado"/><Metric label="QUESTÕES" value={`${questions}`} sub={`${accuracy} acertos · ${pct(accuracy,questions)}%`}/><Metric label="REDAÇÕES" value={`${state.essays.length}`} sub={state.essays[0]?`última: ${state.essays[0].score}`:'comece hoje'}/><Metric label="SIMULADOS" value={`${state.mocks.length}`} sub={state.mocks[0]?`último: ${state.mocks[0].score}/${state.mocks[0].maxScore}`:'sem registros'}/></div><Card><PanelHead kicker="EDITAL" title="Mapa de preparação"/><div className="uem-list">{state.uemTopics.map(x=><div key={x.id} className="uem-row"><div><b>{x.subject}</b><span>{x.topic}</span></div><select value={x.status} onChange={e=>updateTopic(x.id,{status:e.target.value as UemTopicStatus})}><option value="nao-iniciado">Não iniciado</option><option value="estudando">Estudando</option><option value="revisao">Revisão</option><option value="dominado">Dominado</option></select><label>Questões<input type="number" min="0" value={x.questions} onChange={e=>updateTopic(x.id,{questions:Number(e.target.value)})}/></label><label>Acertos<input type="number" min="0" value={x.correct} onChange={e=>updateTopic(x.id,{correct:Number(e.target.value)})}/></label><span className={`priority p${x.priority}`}>P{x.priority}</span></div>)}</div></Card><div className="split"><Card><PanelHead kicker="REDAÇÃO" title="Registrar redação"/><form className="form" onSubmit={addEssay}><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Tema"><input name="theme" required/></Field><Field label="Nota"><input name="score" type="number" step="0.1" min="0"/></Field><Field label="Feedback"><textarea name="notes"/></Field><FormActions/></form></Card><Card><PanelHead kicker="SIMULADO" title="Registrar prova"/><form className="form" onSubmit={addMock}><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Nota"><input name="score" type="number" step="0.1"/></Field></div><div className="cols"><Field label="Nota máxima"><input name="maxScore" type="number" defaultValue="100"/></Field><Field label="Acertos"><input name="correct" type="number"/></Field></div><Field label="Total de questões"><input name="total" type="number"/></Field><Field label="Análise"><textarea name="notes"/></Field><FormActions/></form></Card></div></>}

 function Library(){const doSearch=async()=>{setBookBusy(true);setBookResults(await searchBooks(bookQuery));setBookBusy(false)};const addBook=(r:(typeof bookResults)[number])=>patch('books',v=>[{id:uid('book'),title:r.title,author:r.author,totalPages:r.pages||1,currentPage:0,status:'quero-ler',coverUrl:r.coverUrl,externalId:r.externalId,isbn:r.isbn},...v]);const read=(b:Book,pages:number,minutes:number)=>{patch('readingLogs',v=>[{id:uid('read'),bookId:b.id,date:t,pages,minutes},...v]);patch('books',v=>v.map(x=>x.id===b.id?{...x,currentPage:Math.min(x.totalPages,x.currentPage+pages),status:(x.currentPage+pages>=x.totalPages?'concluido':'lendo') as Book['status']}:x))};return <><Head kicker="BIBLIOTECA" title="Livros" sub="Pesquise catálogos externos, salve capas e acompanhe o progresso real."/><Card><PanelHead kicker="DESCOBRIR" title="Buscar livro na Open Library / Google Books"/><div className="search-row"><label className="search"><Search/><input value={bookQuery} onChange={e=>setBookQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&doSearch()} placeholder="Título, autor ou ISBN..."/></label><button className="btn primary" onClick={doSearch} disabled={bookBusy}>{bookBusy?'Buscando...':'Buscar'}</button></div>{bookResults.length>0&&<div className="catalog-grid">{bookResults.map(r=><article className="catalog-card" key={r.externalId}>{r.coverUrl?<img src={r.coverUrl} alt=""/>:<div className="cover-fallback"><BookOpen/></div>}<div><b>{r.title}</b><small>{r.author}{r.year?` · ${r.year}`:''}</small><p>{r.pages?`${r.pages} páginas`:'Páginas não informadas'}</p><button className="btn small" onClick={()=>addBook(r)}><Plus/>Adicionar</button></div></article>)}</div>}</Card><div className="cards">{state.books.map(b=>{const p=pct(b.currentPage,b.totalPages);return <Card className="book-card" key={b.id}>{b.coverUrl?<img className="book-cover" src={b.coverUrl} alt=""/>:<div className="book-cover placeholder"><BookOpen/></div>}<div className="book-body"><span className="tag">{b.status==='quero-ler'?'Quero ler':b.status==='lendo'?'Lendo':'Concluído'}</span><h3>{b.title}</h3><p>{b.author}</p><Progress value={p}/><small>{b.currentPage}/{b.totalPages} páginas · {p}%</small><div className="inline-form"><input id={`p-${b.id}`} type="number" min="1" placeholder="páginas"/><input id={`m-${b.id}`} type="number" min="1" placeholder="min"/><button className="btn small" onClick={()=>{const pg=Number((document.getElementById(`p-${b.id}`) as HTMLInputElement)?.value)||0;const mi=Number((document.getElementById(`m-${b.id}`) as HTMLInputElement)?.value)||0;if(pg)read(b,pg,mi)}}>Registrar leitura</button><button className="icon danger" onClick={()=>remove('books',b.id)}><Trash2/></button></div></div></Card>})}</div>{state.books.length===0&&<Empty icon={<BookOpen/>} title="Nenhum livro ainda" text="Pesquise acima e adicione sua primeira leitura."/>}</>}

 function Workouts(){const plan=state.workoutPlans.find(x=>x.id===selectedPlan)||state.workoutPlans[0];const doSearch=async()=>{setExerciseBusy(true);setExerciseResults(await searchExercises(exerciseQuery));setExerciseBusy(false)};const addExercise=(r:(typeof exerciseResults)[number])=>{if(!plan)return;patch('workoutPlans',v=>v.map(x=>x.id===plan.id?{...x,exercises:[...x.exercises,{id:uid('ex'),name:r.name,sets:3,reps:'8–12',load:'',restSeconds:90,muscle:r.muscle,equipment:r.equipment,imageUrl:r.imageUrl,externalId:r.externalId}]}:x))};const log=()=>{if(!plan)return;patch('workoutLogs',v=>[{id:uid('workout'),workoutId:plan.id,date:t,duration:60,exercises:plan.exercises.map(e=>({exerciseId:e.id,name:e.name,sets:e.sets,reps:e.reps,load:Number(e.load)||0}))},...v])};return <><Head kicker="TREINO" title="Academia" sub="Ficha, catálogo visual de exercícios, histórico de carga e progressão." actions={<button className="btn primary" onClick={log}><Check/>Concluir treino</button>}/><div className="tabs">{state.workoutPlans.map(x=><button className={x.id===plan?.id?'active':''} key={x.id} onClick={()=>setSelectedPlan(x.id)}>{x.name}</button>)}<button onClick={()=>{const name=prompt('Nome do novo treino:');if(name){const id=uid('plan');patch('workoutPlans',v=>[...v,{id,name,days:[],exercises:[]}]);setSelectedPlan(id)}}}><Plus/>Novo</button></div>{plan&&<><Card><PanelHead kicker="FICHA" title={plan.name}/><div className="exercise-list">{plan.exercises.map(e=><div className="exercise-row" key={e.id}>{e.imageUrl?<img src={e.imageUrl} alt=""/>:<div className="exercise-image"><Dumbbell/></div>}<div><b>{e.name}</b><small>{e.muscle||'Grupo muscular'}{e.equipment?` · ${e.equipment}`:''}</small></div><label>Séries<input type="number" value={e.sets} onChange={x=>patch('workoutPlans',v=>v.map(p=>p.id===plan.id?{...p,exercises:p.exercises.map(q=>q.id===e.id?{...q,sets:Number(x.target.value)}:q)}:p))}/></label><label>Reps<input value={e.reps} onChange={x=>patch('workoutPlans',v=>v.map(p=>p.id===plan.id?{...p,exercises:p.exercises.map(q=>q.id===e.id?{...q,reps:x.target.value}:q)}:p))}/></label><label>Carga<input value={e.load} onChange={x=>patch('workoutPlans',v=>v.map(p=>p.id===plan.id?{...p,exercises:p.exercises.map(q=>q.id===e.id?{...q,load:x.target.value}:q)}:p))}/></label><button className="icon danger" onClick={()=>patch('workoutPlans',v=>v.map(p=>p.id===plan.id?{...p,exercises:p.exercises.filter(q=>q.id!==e.id)}:p))}><Trash2/></button></div>)}</div></Card><Card><PanelHead kicker="CATÁLOGO" title="Buscar exercícios no wger"/><div className="search-row"><label className="search"><Search/><input value={exerciseQuery} onChange={e=>setExerciseQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&doSearch()} placeholder="Ex.: supino, squat, row..."/></label><button className="btn primary" onClick={doSearch}>{exerciseBusy?'Buscando...':'Buscar'}</button></div><div className="catalog-grid exercise-catalog">{exerciseResults.map(r=><article className="catalog-card" key={r.externalId}>{r.imageUrl?<img src={r.imageUrl} alt=""/>:<div className="cover-fallback"><Dumbbell/></div>}<div><b>{r.name}</b><small>{r.muscle}</small><p>{r.equipment||'Equipamento não informado'}</p><button className="btn small" onClick={()=>addExercise(r)}><Plus/>Adicionar à ficha</button></div></article>)}</div></Card></>}<Card><PanelHead kicker="PROGRESSÃO" title="Últimos registros"/><div className="table">{state.workoutLogs.slice(0,20).map(x=><div className="tr" key={x.id}><span>{shortDate(x.date)}</span><b>{state.workoutPlans.find(p=>p.id===x.workoutId)?.name||'Treino'}</b><span>{x.exercises?.map(e=>`${e.name}: ${e.load}kg`).join(' · ')||'Sem cargas registradas'}</span><strong>{x.duration} min</strong></div>)}</div></Card></>}

 function Sports(){const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('sports',v=>[{id:uid('sport'),date:s(f.get('date')),type:s(f.get('type')) as SportType,duration:n(f.get('duration')),distance:n(f.get('distance'))||undefined,notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};const km=state.sports.reduce((a,x)=>a+(x.distance||0),0);return <><Head kicker="MOVIMENTO" title="Corrida, bike e futebol" sub="Acompanhe duração, distância e consistência fora da academia."/><div className="metrics"><Metric label="DISTÂNCIA" value={`${km.toFixed(1)} km`} sub="histórico total"/><Metric label="SESSÕES" value={`${state.sports.length}`} sub="atividades registradas"/><Metric label="SEMANA" value={`${stats.sport} min`} sub="tempo ativo"/></div><div className="split"><Card><PanelHead kicker="REGISTRAR" title="Nova atividade"/><form className="form" onSubmit={submit}><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Tipo"><select name="type"><option value="corrida">Corrida</option><option value="bike">Bike</option><option value="futebol">Futebol</option><option value="caminhada">Caminhada</option><option value="outro">Outro</option></select></Field></div><div className="cols"><Field label="Duração (min)"><input name="duration" type="number" required/></Field><Field label="Distância (km)"><input name="distance" type="number" step="0.01"/></Field></div><Field label="Observações"><textarea name="notes"/></Field><FormActions/></form></Card><Card><PanelHead kicker="HISTÓRICO" title="Atividades"/><div className="history">{state.sports.slice(0,20).map(x=><div key={x.id}><Activity/><span><b>{x.type}</b><small>{shortDate(x.date)} · {x.duration} min{x.distance?` · ${x.distance} km`:''}</small></span><button className="icon danger" onClick={()=>remove('sports',x.id)}><Trash2/></button></div>)}</div></Card></div></>}

 function Nutrition(){const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('meals',v=>[{id:uid('meal'),date:s(f.get('date')),type:s(f.get('type')) as MealType,name:s(f.get('name')),calories:n(f.get('calories'))||undefined,protein:n(f.get('protein'))||undefined,notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};const water=state.water.find(x=>x.date===t)?.ml||0;const setWater=(ml:number)=>patch('water',v=>[...v.filter(x=>x.date!==t),{date:t,ml:Math.max(0,ml)}]);return <><Head kicker="ENERGIA" title="Nutrição" sub="Quatro refeições, água e visão simples da alimentação diária."/><div className="metrics"><Metric label="REFEIÇÕES HOJE" value={`${state.meals.filter(x=>x.date===t).length}/4`} sub="meta diária"/><Metric label="ÁGUA" value={`${(water/1000).toFixed(1)} L`} sub="meta sugerida: ajuste à sua rotina"/><Metric label="PROTEÍNA" value={`${state.meals.filter(x=>x.date===t).reduce((a,x)=>a+(x.protein||0),0)} g`} sub="registrada hoje"/></div><div className="split"><Card><PanelHead kicker="REGISTRAR" title="Refeição"/><form className="form" onSubmit={submit}><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Tipo"><select name="type"><option value="cafe">Café</option><option value="almoco">Almoço</option><option value="lanche">Lanche</option><option value="jantar">Jantar</option><option value="outro">Outro</option></select></Field></div><Field label="Descrição"><input name="name" required placeholder="Ex.: arroz, feijão e frango"/></Field><div className="cols"><Field label="Calorias (opcional)"><input name="calories" type="number"/></Field><Field label="Proteína g (opcional)"><input name="protein" type="number"/></Field></div><FormActions/></form></Card><Card><PanelHead kicker="HIDRATAÇÃO" title="Água hoje"/><div className="water"><strong>{water} ml</strong><div><button className="btn ghost" onClick={()=>setWater(water-250)}><Minus/>250</button><button className="btn primary" onClick={()=>setWater(water+250)}><Plus/>250 ml</button></div><Progress value={pct(water,2500)}/></div><div className="history">{state.meals.filter(x=>x.date===t).map(x=><div key={x.id}><Apple/><span><b>{x.name}</b><small>{x.type}{x.calories?` · ${x.calories} kcal`:''}</small></span><button className="icon danger" onClick={()=>remove('meals',x.id)}><Trash2/></button></div>)}</div></Card></div></>}

 function Sleep(){const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('sleep',v=>[{id:uid('sleep'),date:s(f.get('date')),bedTime:s(f.get('bed')),wakeTime:s(f.get('wake')),hours:n(f.get('hours')),quality:n(f.get('quality'),3),notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};const avg=state.sleep.slice(0,7).reduce((a,x)=>a+x.hours,0)/Math.max(1,state.sleep.slice(0,7).length);return <><Head kicker="RECUPERAÇÃO" title="Sono" sub="Horários, duração, qualidade e consistência."/><div className="metrics"><Metric label="MÉDIA" value={`${avg.toFixed(1)}h`} sub="últimos registros"/><Metric label="META" value="8h" sub="por noite"/><Metric label="REGISTROS" value={`${state.sleep.length}`} sub="noites acompanhadas"/></div><div className="split"><Card><PanelHead kicker="REGISTRAR" title="Noite"/><form className="form" onSubmit={submit}><Field label="Data ao acordar"><input name="date" type="date" defaultValue={t}/></Field><div className="cols"><Field label="Dormiu"><input name="bed" type="time" defaultValue="23:00"/></Field><Field label="Acordou"><input name="wake" type="time" defaultValue="07:00"/></Field></div><div className="cols"><Field label="Horas"><input name="hours" type="number" step="0.1" defaultValue="8"/></Field><Field label="Qualidade 1–5"><input name="quality" type="number" min="1" max="5" defaultValue="4"/></Field></div><FormActions/></form></Card><Card><PanelHead kicker="HISTÓRICO" title="Últimas noites"/><div className="history">{state.sleep.slice(0,14).map(x=><div key={x.id}><Moon/><span><b>{x.hours}h · qualidade {x.quality}/5</b><small>{shortDate(x.date)} · {x.bedTime} → {x.wakeTime}</small></span><button className="icon danger" onClick={()=>remove('sleep',x.id)}><Trash2/></button></div>)}</div></Card></div></>}

 function Projects(){const addProject=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('projects',v=>[{id:uid('project'),name:s(f.get('name')),description:s(f.get('description')),status:'ideia',tech:s(f.get('tech')).split(',').map(x=>x.trim()).filter(Boolean),hours:0,tasks:[],repoUrl:s(f.get('repo'))},...v]);e.currentTarget.reset()};return <><Head kicker="PORTFÓLIO" title="Projetos" sub="Do backlog ao deploy: tarefas, tecnologias, horas e status."/><Card><details><summary><Plus/>Adicionar projeto</summary><form className="form wide-form" onSubmit={addProject}><Field label="Nome"><input name="name" required/></Field><Field label="Descrição"><textarea name="description"/></Field><div className="cols"><Field label="Tecnologias"><input name="tech" placeholder="Java, React, PostgreSQL"/></Field><Field label="Repositório"><input name="repo" placeholder="https://github.com/..."/></Field></div><FormActions/></form></details></Card><div className="project-grid">{state.projects.map(p=><Card key={p.id} className="project-card"><div className="project-top"><span className="tag">{p.status}</span><select value={p.status} onChange={e=>patch('projects',v=>v.map(x=>x.id===p.id?{...x,status:e.target.value as ProjectStatus}:x))}><option value="ideia">Ideia</option><option value="andamento">Andamento</option><option value="pausado">Pausado</option><option value="concluido">Concluído</option></select></div><h3>{p.name}</h3><p>{p.description}</p><div className="chips">{p.tech.map(x=><span key={x}>{x}</span>)}</div><div className="project-meta"><input type="number" min="0" value={p.hours} onChange={e=>patch('projects',v=>v.map(x=>x.id===p.id?{...x,hours:Number(e.target.value)}:x))}/><small>horas investidas</small></div><div className="task-list">{p.tasks.map(task=><button className={task.done?'done':''} key={task.id} onClick={()=>patch('projects',v=>v.map(x=>x.id===p.id?{...x,tasks:x.tasks.map(q=>q.id===task.id?{...q,done:!q.done}:q)}:x))}><span>{task.done&&<Check/>}</span>{task.title}</button>)}</div><div className="inline-form"><input id={`task-${p.id}`} placeholder="Nova tarefa..."/><button className="btn small" onClick={()=>{const input=document.getElementById(`task-${p.id}`) as HTMLInputElement;if(input.value.trim()){patch('projects',v=>v.map(x=>x.id===p.id?{...x,tasks:[...x.tasks,{id:uid('task'),title:input.value.trim(),done:false}]}:x));input.value=''}}}><Plus/>Tarefa</button><button className="icon danger" onClick={()=>remove('projects',p.id)}><Trash2/></button></div></Card>)}</div>{state.projects.length===0&&<Empty icon={<FolderKanban/>} title="Nenhum projeto" text="Adicione o portfólio, rastreador financeiro, jogo web e outros projetos."/>}</>}

 function Career(){const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('applications',v=>[{id:uid('job'),company:s(f.get('company')),role:s(f.get('role')),date:s(f.get('date')),status:'aplicada',url:s(f.get('url')),notes:s(f.get('notes'))},...v]);e.currentTarget.reset()};return <><Head kicker="CARREIRA" title="Vagas e entrevistas" sub="Pipeline de candidaturas para transformar procura em processo."/><div className="split"><Card><PanelHead kicker="NOVA" title="Candidatura"/><form className="form" onSubmit={submit}><Field label="Empresa"><input name="company" required/></Field><Field label="Vaga"><input name="role" required/></Field><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Link"><input name="url"/></Field></div><Field label="Notas"><textarea name="notes"/></Field><FormActions/></form></Card><Card><PanelHead kicker="PIPELINE" title={`${state.applications.length} candidaturas`}/><div className="history">{state.applications.map(x=><div key={x.id}><BriefcaseBusiness/><span><b>{x.role} · {x.company}</b><small>{shortDate(x.date)}</small></span><select value={x.status} onChange={e=>patch('applications',v=>v.map(q=>q.id===x.id?{...q,status:e.target.value as ApplicationStatus}:q))}><option value="salva">Salva</option><option value="aplicada">Aplicada</option><option value="entrevista">Entrevista</option><option value="teste">Teste</option><option value="oferta">Oferta</option><option value="rejeitada">Rejeitada</option></select><button className="icon danger" onClick={()=>remove('applications',x.id)}><Trash2/></button></div>)}</div></Card></div></>}

 function Finance(){const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('finances',v=>[{id:uid('fin'),date:s(f.get('date')),type:s(f.get('type')) as FinanceType,category:s(f.get('category')),description:s(f.get('description')),amount:n(f.get('amount'))},...v]);e.currentTarget.reset()};const income=state.finances.filter(x=>x.type==='receita').reduce((a,x)=>a+x.amount,0),expense=state.finances.filter(x=>x.type==='despesa').reduce((a,x)=>a+x.amount,0);return <><Head kicker="DINHEIRO" title="Finanças" sub="Receitas, despesas e visão clara do saldo."/><div className="metrics"><Metric label="SALDO" value={money(income-expense)} sub="histórico" tone="green"/><Metric label="RECEITAS" value={money(income)} sub="entradas"/><Metric label="DESPESAS" value={money(expense)} sub="saídas" tone="amber"/></div><div className="split"><Card><PanelHead kicker="LANÇAR" title="Movimentação"/><form className="form" onSubmit={submit}><div className="cols"><Field label="Data"><input name="date" type="date" defaultValue={t}/></Field><Field label="Tipo"><select name="type"><option value="despesa">Despesa</option><option value="receita">Receita</option></select></Field></div><Field label="Descrição"><input name="description" required/></Field><div className="cols"><Field label="Categoria"><input name="category" placeholder="Alimentação, salário..."/></Field><Field label="Valor"><input name="amount" type="number" step="0.01" required/></Field></div><FormActions/></form></Card><Card><PanelHead kicker="HISTÓRICO" title="Movimentações"/><div className="history">{state.finances.slice(0,30).map(x=><div key={x.id}><WalletCards/><span><b>{x.description}</b><small>{x.category} · {shortDate(x.date)}</small></span><strong className={x.type}>{x.type==='receita'?'+':'-'}{money(x.amount)}</strong><button className="icon danger" onClick={()=>remove('finances',x.id)}><Trash2/></button></div>)}</div></Card></div></>}

 function Goals(){const addGoal=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('goals',v=>[...v,{id:uid('goal'),title:s(f.get('title')),current:0,target:n(f.get('target')),unit:s(f.get('unit')),deadline:s(f.get('deadline'))}]);e.currentTarget.reset()};const addHabit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);patch('habits',v=>[...v,{id:uid('habit'),name:s(f.get('name')),targetPerWeek:n(f.get('target'),7),category:s(f.get('category')) as EventCategory,xp:n(f.get('xp'),20)}]);e.currentTarget.reset()};return <><Head kicker="DIREÇÃO" title="Metas e hábitos" sub="Resultados no horizonte, comportamento no presente."/><div className="split"><Card><PanelHead kicker="METAS" title="Resultados"/><div className="goal-list">{state.goals.map(g=><div key={g.id}><div><b>{g.title}</b><small>{g.current}/{g.target} {g.unit}</small></div><Progress value={pct(g.current,g.target)}/><div className="stepper"><button onClick={()=>patch('goals',v=>v.map(x=>x.id===g.id?{...x,current:Math.max(0,x.current-1)}:x))}>−</button><button onClick={()=>patch('goals',v=>v.map(x=>x.id===g.id?{...x,current:Math.min(x.target,x.current+1)}:x))}>+</button><button className="danger" onClick={()=>remove('goals',g.id)}><Trash2/></button></div></div>)}</div><details><summary><Plus/>Nova meta</summary><form className="form" onSubmit={addGoal}><Field label="Meta"><input name="title" required/></Field><div className="cols"><Field label="Alvo"><input name="target" type="number" required/></Field><Field label="Unidade"><input name="unit" required/></Field></div><Field label="Prazo"><input name="deadline" type="date"/></Field><FormActions/></form></details></Card><Card><PanelHead kicker="HÁBITOS" title="Sistema semanal"/><div className="habit-manage">{state.habits.map(h=><div key={h.id}><b>{h.name}</b><small>{h.targetPerWeek}x/semana · +{h.xp} XP</small><button className="icon danger" onClick={()=>remove('habits',h.id)}><Trash2/></button></div>)}</div><details><summary><Plus/>Novo hábito</summary><form className="form" onSubmit={addHabit}><Field label="Hábito"><input name="name" required/></Field><div className="cols"><Field label="Meta semanal"><input name="target" type="number" defaultValue="7"/></Field><Field label="XP"><input name="xp" type="number" defaultValue="20"/></Field></div><Field label="Categoria"><select name="category">{Object.entries(labels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></Field><FormActions/></form></details></Card></div></>}

 function Yearly(){const y=new Date().getFullYear();const inYear=(d:string)=>d.startsWith(String(y));const study=state.studyLogs.filter(x=>inYear(x.date)).reduce((a,x)=>a+x.minutes,0)+state.focusLogs.filter(x=>inYear(x.date)).reduce((a,x)=>a+x.minutes,0);const books=state.books.filter(x=>x.status==='concluido').length;const workouts=state.workoutLogs.filter(x=>inYear(x.date)).length;const km=state.sports.filter(x=>inYear(x.date)).reduce((a,x)=>a+(x.distance||0),0);const projects=state.projects.filter(x=>x.status==='concluido').length;const applications=state.applications.filter(x=>inYear(x.date)).length;return <><Head kicker="RETROSPECTIVA" title={`${y} em números`} sub="Seu próprio Wrapped: evidências do que você construiu."/><div className="year-grid"><Metric label="HORAS DE ESTUDO" value={`${(study/60).toFixed(0)}h`} sub="foco + sessões"/><Metric label="LIVROS" value={`${books}`} sub="concluídos" tone="purple"/><Metric label="TREINOS" value={`${workouts}`} sub="academia" tone="green"/><Metric label="DISTÂNCIA" value={`${km.toFixed(0)} km`} sub="corrida + bike" tone="amber"/><Metric label="PROJETOS" value={`${projects}`} sub="concluídos"/><Metric label="CANDIDATURAS" value={`${applications}`} sub="enviadas" tone="purple"/><Metric label="XP TOTAL" value={`${stats.xp}`} sub={`nível ${stats.level}`} tone="green"/><Metric label="MELHOR STREAK" value={`${stats.streak}d`} sub="sequência atual" tone="amber"/></div><Card className="hero-quote"><Trophy/><div><small>REGRA DO SISTEMA</small><h2>O que não é medido vira memória vaga. O que é registrado vira evolução.</h2></div></Card></>}

 function Review(){const start=ws;const old=state.weeklyReviews.find(x=>x.weekStart===start);const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={weekStart:start,rating:n(f.get('rating'),5),wins:s(f.get('wins')),challenges:s(f.get('challenges')),nextFocus:s(f.get('nextFocus'))};patch('weeklyReviews',v=>[item,...v.filter(x=>x.weekStart!==start)]);alert('Revisão semanal salva.')};return <><Head kicker="FEEDBACK LOOP" title="Revisão semanal" sub="Transforme uma semana vivida em decisões para a próxima."/><div className="split"><Card><PanelHead kicker={`SEMANA DE ${shortDate(start)}`} title="Fechamento"/><form className="form" onSubmit={submit}><Field label="Nota da semana (1–10)"><input name="rating" type="number" min="1" max="10" defaultValue={old?.rating||7}/></Field><Field label="Vitórias"><textarea name="wins" defaultValue={old?.wins} placeholder="O que funcionou?"/></Field><Field label="Obstáculos"><textarea name="challenges" defaultValue={old?.challenges} placeholder="O que atrapalhou?"/></Field><Field label="Foco da próxima semana"><textarea name="nextFocus" defaultValue={old?.nextFocus} placeholder="O que vai mudar?"/></Field><FormActions/></form></Card><Card><PanelHead kicker="SEMANA" title="Resumo automático"/><div className="review-stats"><div><b>{(stats.studyMinutes/60).toFixed(1)}h</b><small>estudo</small></div><div><b>{stats.workouts}</b><small>treinos</small></div><div><b>{stats.pages}</b><small>páginas</small></div><div><b>{stats.sport}m</b><small>esporte</small></div></div><p className="muted-text">Use os números como diagnóstico, não como julgamento. Ajuste o plano para torná-lo executável.</p></Card></div></>}

 function SettingsPage(){const auth=async(mode:'in'|'up')=>{try{setCloudStatus('Conectando...');if(mode==='in')await signIn(authEmail,authPassword);else await signUp(authEmail,authPassword);setCloudStatus(mode==='up'?'Conta criada; confirme o e-mail se necessário.':'Conectado')}catch(e){setCloudStatus(e instanceof Error?e.message:'Erro ao autenticar')}};const push=async()=>{if(!session?.user)return;try{setCloudStatus('Enviando...');await pushCloud(session.user.id,state);setCloudStatus('Sincronizado com a nuvem')}catch(e){setCloudStatus(e instanceof Error?e.message:'Erro de sync')}};const pull=async()=>{if(!session?.user)return;try{setCloudStatus('Baixando...');const remote=await pullCloud(session.user.id);if(remote&&confirm('Substituir os dados locais pelos dados da nuvem?'))setState({...seedState,...remote,version:3});setCloudStatus(remote?'Dados carregados':'Nenhum backup na nuvem ainda')}catch(e){setCloudStatus(e instanceof Error?e.message:'Erro de sync')}};return <><Head kicker="SISTEMA" title="Configurações" sub="Backup, nuvem, instalação e portabilidade dos seus dados."/><div className="settings-grid"><Card><PanelHead kicker="NUVEM" title="Supabase" action={cloudEnabled?<Cloud/>:<CloudOff/>}/>{cloudEnabled?(session?<><p>Conectado como <b>{session.user.email}</b>.</p><div className="actions wrap"><button className="btn primary" onClick={push}><Upload/>Enviar para nuvem</button><button className="btn ghost" onClick={pull}><Download/>Baixar da nuvem</button><button className="btn ghost" onClick={()=>signOut()}><LogOut/>Sair</button></div></>:<><p>Entre para sincronizar computador e celular.</p><div className="form"><Field label="E-mail"><input value={authEmail} onChange={e=>setAuthEmail(e.target.value)} type="email"/></Field><Field label="Senha"><input value={authPassword} onChange={e=>setAuthPassword(e.target.value)} type="password"/></Field><div className="actions"><button className="btn primary" onClick={()=>auth('in')}><LogIn/>Entrar</button><button className="btn ghost" onClick={()=>auth('up')}>Criar conta</button></div></div></>):<><p>Modo local ativo. Para ativar a nuvem, crie <code>.env.local</code> usando <code>.env.example</code>.</p></>}<p className="status">{cloudStatus}</p></Card><Card><PanelHead kicker="BACKUP" title="Seus dados"/><p>Faça exportações periódicas. O JSON contém todo o estado da aplicação.</p><div className="actions wrap"><button className="btn primary" onClick={backup}><Download/>Exportar JSON</button><label className="btn ghost file"><Upload/>Importar<input type="file" accept="application/json" onChange={e=>e.target.files?.[0]&&restore(e.target.files[0])}/></label><button className="btn danger-btn" onClick={reset}><Trash2/>Restaurar padrão</button></div></Card><Card><PanelHead kicker="PWA" title="Instalar como aplicativo" action={<MonitorUp/>}/><p>Quando publicado em HTTPS, use a opção “Instalar aplicativo” do navegador. O service worker já está configurado para funcionar como PWA.</p></Card><Card><PanelHead kicker="INTEGRAÇÕES" title="Calendário e APIs"/><p>Use o exportador <b>.ics</b> do calendário para Google Calendar, Outlook ou Apple Calendar. Livros usam Open Library/Google Books; exercícios usam wger.</p></Card></div></>}

 const page=()=>{switch(view){case'today':return Today();case'calendar':return Calendar();case'focus':return Focus();case'study':return Study();case'uem':return Uem();case'library':return Library();case'workouts':return Workouts();case'sports':return Sports();case'nutrition':return Nutrition();case'sleep':return Sleep();case'projects':return Projects();case'career':return Career();case'finance':return Finance();case'goals':return Goals();case'yearly':return Yearly();case'review':return Review();default:return SettingsPage()}};
 return <Layout>{page()}</Layout>
}
